layer.css:
[data-ryt="footer"] { color: var(--ryt-muted); border-top: 1px solid rgb(236, 233, 233); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: rgb(50, 55, 57); border-radius: 0px; font-family: "chillax variable", ui-sans-serif, system-ui, sans-serif; font-size: 27.2px; font-weight: 520; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(50, 55, 57); text-decoration-thickness: auto; text-underline-offset: auto; transition: color cubic-bezier(0.4, 0, 0.2, 1), background-color cubic-bezier(0.4, 0, 0.2, 1), border-color cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: "chillax variable", ui-sans-serif, system-ui, sans-serif; font-size: 17.5px; font-weight: 500; font-style: normal; line-height: 1.4; letter-spacing: 0.7px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color cubic-bezier(0.4, 0, 0.2, 1), background-color cubic-bezier(0.4, 0, 0.2, 1), border-color cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="category"], [data-ryt="tags"] li { color: rgb(85, 85, 85); background-color: rgb(242, 240, 237); border-radius: 999px; font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Noto Sans SC", "Microsoft YaHei", sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(85, 85, 85); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 2px; padding-right: 8px; padding-bottom: 2px; padding-left: 8px; transition: color cubic-bezier(0.4, 0, 0.2, 1), background-color cubic-bezier(0.4, 0, 0.2, 1), border-color cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="review"] { color: var(--ryt-muted); font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Noto Sans SC", "Microsoft YaHei", sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: color cubic-bezier(0.4, 0, 0.2, 1), background-color cubic-bezier(0.4, 0, 0.2, 1), border-color cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Noto Sans SC", "Microsoft YaHei", sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: color cubic-bezier(0.4, 0, 0.2, 1), background-color cubic-bezier(0.4, 0, 0.2, 1), border-color cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Noto Sans SC", "Microsoft YaHei", sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(26, 26, 26); border-radius: 0px; font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Noto Sans SC", "Microsoft YaHei", sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-size: 21px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(26, 26, 26); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #006cac }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #005a8a }
